function useOrderUpdates(orderId) {
  useEffect(() => {
    const seenEventIds = new Set(); // dedupe by event ID
    const socket = connectWithBackoff(`/ws/orders/${orderId}`);
    socket.onmessage = (e) => {
      const event = JSON.parse(e.data);
      if (seenEventIds.has(event.id)) return; // ignore duplicate delivery
      seenEventIds.add(event.id);
      applyUpdate(event);
    };
    socket.onclose = () => scheduleReconnectWithBackoff(orderId);
    return () => socket.close();
  }, [orderId]);
}

